 d:[[0,"Marek, I'd like to request a budget of €40,000 for next year's training programme."],[1,"That's a lot. What's the breakdown?"],[0,"The breakdown is as follows: €25,000 goes on trainers, €10,000 on online licences and €5,000 on travel."],[1,"Are these one-off costs?"],[0,"Most of them are, apart from the licences, which are a recurring cost — €10,000 every year."],[1,"I have to be honest, there's no room in the budget for big new projects. We need to cut costs by 5%."],[0,"I understand. But this would pay for itself within a year."],[1,"How?"],[0,"Staff turnover cost us €120,000 last year in recruitment. If training reduces turnover by a third, it would save us €40,000 a year."],[1,"Hmm. Send me the numbers and I'll take it to the board."]],
 q:[["How much does Anna ask for?","€25,000","€40,000","€120,000","€10,000",1],["Which cost is recurring?","Trainers","Licences","Travel","All of them",1],["Why is Marek worried?","He doesn't like training.","They need to cut costs by 5%.","The board said no.","Anna made a mistake.",1],["How would the programme pay for itself?","By reducing staff turnover","By selling training","By cutting salaries","By raising prices",0]],
 f:[["I want money 40k.","I'd like to request a budget of €40,000.",["i'd like to request","budget of"]],["We spend for trainers 25k.","€25,000 goes on trainers.",["goes on","spend on"]],["No money in budget.","There's no room in the budget for that.",["no room in the budget"]],["It gives back money in a year.","This would pay for itself within a year.",["pay for itself"]]],
