bz23l3:{w:["What's the difference between revenue and profit?","Why can a company with good sales still have no money in the bank?"],
 c:"The CFO, Ms Lee, explains the year's results to the sales team, who are not finance experts.",
 p:[["Ms Lee","CFO"],["Bartek","Sales Manager"]],
 d:[[0,"Let me explain this year's results in simple terms. The good news is that revenue went up by 12%."],[1,"So we made more money?"],[0,"We sold more, yes. But although revenue went up, net profit went down by 20%."],[1,"How is that possible?"],[0,"Put simply, transport costs rose by almost a third. We sold more but earned less on each order."],[1,"I see. And why do we keep hearing about cash flow?"],[0,"Because clients pay us after 75 days on average, but we pay our suppliers after 30. We're making money, but it's coming in too slowly."],[1,"So what does it mean for my team?"],[0,"What this means for you is that we'd like shorter payment terms in new contracts — 30 days if possible. Does that make sense?"],[1,"Yes. Despite the good sales, we need to be smarter about terms."],[0,"Exactly."]],
 q:[["What happened to revenue?","It went down 20%.","It went up 12%.","It stayed the same.","It doubled.",1],["Why did net profit fall?","Fewer sales","Transport costs rose by almost a third","Higher salaries","A big client left",1],["What's the cash-flow problem?","Clients pay after 75 days, the company pays suppliers after 30.","There's no money at all.","Prices are too low.","The bank closed.",0],["What should the sales team do?","Ask for shorter payment terms in new contracts","Sell less","Raise prices by 30%","Stop using transport",0]],
 f:[["Despite revenue went up, profit went down.","Although revenue went up, profit went down.",["although revenue"]],["Money is slow.","We're making money, but it's coming in too slowly.",["coming in too slowly","cash flow"]],["Profit is the money from sales.","Revenue is the money from sales; profit is what's left after costs.",["revenue","after costs"]],["You understand?","Does that make sense?",["does that make sense"]]],
 r:{h:"Explain results to non-experts",s:"Explain your company's results to a team with no finance background: revenue, profit, one reason, cash flow and what it means for them.",b:["Give the good news and the bad news","Use 'although' or 'despite'","Explain cash flow simply","Say what it means for them and check understanding"]},
 wr:{h:"Results in plain English",s:"Write a short message to your team explaining: revenue +12%, net profit –20% (transport costs), cash flow problem, and what you need from them.",to:"sales-team@company.com",su:"This year's results — in plain English",min:100}},

